# app/systems/accounting/services/journal_entries/lock_guard.rb
module Accounting
  module JournalEntries
    # Central rules for when a journal entry may be created, changed
    # (including state changes such as approve/unapprove) or deleted.
    #
    # Changes made by users:
    #   - only in fiscal years that are open (not closing or closed);
    #   - never to entries generated by the system (revaluation, closing).
    #
    # Changes made by system services (the entry's `system_context` is set,
    # e.g. :currency_revaluation or :fiscal_year_closing):
    #   - allowed in open and closing fiscal years, never in closed ones.
    #
    # Both the fiscal year the entry is in and the one it is being moved to
    # are checked.
    #
    # Users also can't change booked or approved items whose balance is
    # locked by a posted permanent currency revaluation (monetary account in
    # a foreign currency, inside its scope, dated on or before its date) —
    # neither the item as stored nor as changed.
    class LockGuard
      # permanent_locks: an Accounting::Revaluation::PermanentLocks to reuse
      # when checking many entries (e.g. when rendering a list).
      def initialize(entry, permanent_locks: nil)
        @entry = entry
        @permanent_locks = permanent_locks
      end

      # Messages explaining why the entry can't be saved; empty when allowed.
      def save_violations
        violations
      end

      # Messages explaining why the entry can't be destroyed; empty when allowed.
      def destroy_violations
        violations(include_new_fiscal_year: false)
      end

      # Why a user can't change this entry right now, or nil. Used by the UI
      # to show entries read-only.
      def manual_change_reason
        return nil if entry.new_record?

        manual_violations([ entry.fiscal_year ].compact, system_generated: persisted_system_generated?).first ||
          permanent_lock_messages(stored_snapshots).first
      end

      private

      attr_reader :entry

      def violations(include_new_fiscal_year: true)
        years = fiscal_years(include_new_fiscal_year)

        if entry.system_context.present?
          system_violations(years)
        else
          snapshots = stored_snapshots
          snapshots += new_snapshots if include_new_fiscal_year
          manual_violations(years, system_generated: persisted_system_generated? || entry.system_generated?) +
            permanent_lock_messages(snapshots)
        end
      end

      Snapshot = Struct.new(:account_id, :currency_id, :center_ids, :date)

      # Items as stored, when the stored entry counts in balances.
      def stored_snapshots
        return [] unless entry.persisted? && entry.state_in_database.present? && entry.state_in_database != "draft"

        entry.items.select(&:persisted?).map do |item|
          Snapshot.new(item.account_id_in_database, item.currency_id_in_database,
                       (1..6).map { |level| item.attribute_in_database("center#{level}_id") },
                       entry.date_in_database)
        end
      end

      # Items as they will be saved, when the entry will count in balances.
      def new_snapshots
        return [] if entry.state.blank? || entry.draft?

        entry.items.reject(&:marked_for_destruction?).map do |item|
          Snapshot.new(item.account_id, item.currency_id, (1..6).map { |level| item.public_send("center#{level}_id") }, entry.date)
        end
      end

      def permanent_lock_messages(snapshots)
        snapshots = snapshots.select { |s| s.account_id && s.date }
        return [] if snapshots.empty?

        locks = permanent_locks
        return [] unless locks.any_on_or_after?(snapshots.map(&:date).min)

        locks.preload_accounts(snapshots.map(&:account_id))
        snapshots.filter_map do |snapshot|
          locks.blocking(account_id: snapshot.account_id, currency_id: snapshot.currency_id,
                         center_ids: snapshot.center_ids, date: snapshot.date)
        end.uniq.map { |revaluation| entry.model_t("errors.locked_by_revaluation", date: revaluation.as_of_date) }
      end

      def permanent_locks
        @permanent_locks ||= Accounting::Revaluation::PermanentLocks.new(entry.organization)
      end

      def system_violations(years)
        years.select(&:closed?).map { |fy| message("fiscal_year_closed", fy) }.uniq
      end

      def manual_violations(years, system_generated:)
        messages = []
        messages << entry.model_t("errors.system_generated_locked") if system_generated

        years.each do |fy|
          if fy.closing?
            messages << message("fiscal_year_closing", fy)
          elsif fy.closed?
            messages << message("fiscal_year_closed", fy)
          end
        end

        messages.uniq
      end

      # The fiscal year the entry is stored in and, on save, the one it is
      # being assigned to.
      def fiscal_years(include_new_fiscal_year)
        years = []
        if entry.persisted? && entry.fiscal_year_id_in_database.present?
          stored_id = entry.fiscal_year_id_in_database
          years << (stored_id == entry.fiscal_year&.id ? entry.fiscal_year : FiscalYear.find_by(id: stored_id))
        end
        years << entry.fiscal_year if include_new_fiscal_year || entry.new_record?
        years.compact.uniq
      end

      def persisted_system_generated?
        entry.persisted? && entry.source_type_in_database.present?
      end

      def message(key, fiscal_year)
        entry.model_t("errors.#{key}", fiscal_year: fiscal_year.name)
      end
    end
  end
end
